def run_idempotent(handler, state, user, method, path, headers_get, body):
    key = headers_get("Idempotency-Key")
    if key is None or key == "":
        raise ApiError(400, "missing_idempotency_key", "Idempotency-Key header is required")
    if len(key) > 255:
        raise ApiError(422, "validation_failed", "Idempotency-Key must be at most 255 characters")
    record_key = (user.id, method, path, key)
    with STATE_LOCK:
        st = state_module.STATE
        existing = st.idempotency.get(record_key)
        if existing is not None:
            if json_equal(existing.request_body, body):
                return 200, existing.response_body
            raise ApiError(409, "idempotency_key_reuse", "key already used with a different request body")
        record = IdempotencyRecord(...in_flight...)
        st.idempotency[record_key] = record
        try:
            status, payload = handler(state=st, user=user, body=body, params=params, query=query)
        except ApiError:
            del st.idempotency[record_key]
            raise
        record.status = "done"
        record.response_status = status
        record.response_body = payload
        return status, payload
