import ast, builtins, sys

BUILTINS = set(dir(builtins))

def module_names(tree):
    names = set()
    for node in tree.body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for a in node.names:
                names.add((a.asname or a.name).split(".")[0])
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, ast.Assign):
            for t in node.targets:
                if isinstance(t, ast.Name):
                    names.add(t.id)
                elif isinstance(t, ast.Tuple):
                    names.update(x.id for x in t.elts if isinstance(x, ast.Name))
        elif isinstance(node, (ast.For, ast.If, ast.Try, ast.With)):
            for sub in ast.walk(node):
                if isinstance(sub, ast.Assign):
                    for t in sub.targets:
                        if isinstance(t, ast.Name):
                            names.add(t.id)
    return names

def check(path):
    tree = ast.parse(open(path).read())
    globals_ = module_names(tree) | BUILTINS
    problems = []

    def local_names(fn):
        names = set()
        for arg in getattr(fn.args, "args", []) + getattr(fn.args, "kwonlyargs", []):
            names.add(arg.arg)
        for sub in ast.walk(fn):
            if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Store):
                names.add(sub.id)
            elif isinstance(sub, ast.comprehension):
                for t in ast.walk(sub.target):
                    if isinstance(t, ast.Name):
                        names.add(t.id)
            elif isinstance(sub, (ast.FunctionDef, ast.AsyncFunctionDef)):
                names.add(sub.name)
        return names

    def walk(node, visible):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                walk(child, visible | local_names(child))
            elif isinstance(child, ast.Lambda):
                walk(child, visible | {a.arg for a in child.args.args})
            elif isinstance(child, ast.Name) and isinstance(child.ctx, ast.Load):
                if child.id not in visible:
                    problems.append((path, child.lineno, child.id))
            else:
                walk(child, visible)

    walk(tree, globals_)
    return problems

allp = []
for f in ["client.py", "run.py", "test_timestamps.py", "test_me_temporal.py",
          "test_statement.py", "test_corrections.py", "test_snapshots.py",
          "test_upgrade_settlements.py", "test_holds.py", "test_invariants.py"]:
    allp += check(f)
for p in sorted(set(allp)):
    print("UNDEFINED:", p)
print("sweep done,", len(set(allp)), "issues")
